export type ParsedExecuteBuybackInstruction<
  TProgram extends string = typeof LEVERMEME_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    authority: TAccountMetas[0];
    protocol: TAccountMetas[1];
    revenue: TAccountMetas[2];
    inputMint: TAccountMetas[3];
    inputTokens: TAccountMetas[4];
    leverMint: TAccountMetas[5];
    leverTokens: TAccountMetas[6];
    inputProgram: TAccountMetas[7];
    leverProgram: TAccountMetas[8];
    jupiterProgram: TAccountMetas[9];
  };
  data: ExecuteBuybackInstructionData;
};

export function parseExecuteBuybackInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedExecuteBuybackInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      protocol: getNextAccount(),
      revenue: getNextAccount(),
      inputMint: getNextAccount(),
      inputTokens: getNextAccount(),
      leverMint: getNextAccount(),
      leverTokens: getNextAccount(),
      inputProgram: getNextAccount(),
      leverProgram: getNextAccount(),
      jupiterProgram: getNextAccount(),
    },
    data: getExecuteBuybackInstructionDataDecoder().decode(instruction.data),
  };
}
